export const miloMissions=[
{id:'supplies',title:'Un camp accueillant',hint:'Rapporte 8 bois et 6 baies à Milo.',cost:{wood:8,berries:6},reward:8},
{id:'furniture',title:'Le coin des amis',hint:'Construis puis pose un banc et une table à moins de 24 blocs du camp.',furniture:['bench','table'],reward:12},
{id:'companions',title:'Une nouvelle amitié',hint:'Apprivoise au moins deux compagnons, puis reviens voir Milo.',friends:2,reward:10},
{id:'savanna',title:'Des nouvelles de la savane',hint:'Visite la savane, puis raconte ton voyage à Milo.',visit:'africa',reward:15},
{id:'treasure',title:'Les secrets des cristaux',hint:'Trouve le trésor du labyrinthe et reviens voir Milo.',treasure:true,reward:20}];
export function normalizeMilo(value){return {claimed:[...new Set((Array.isArray(value?.claimed)?value.claimed:[]).filter(id=>miloMissions.some(m=>m.id===id)))]};}
export function currentMilo(state){return miloMissions.find(m=>!state.claimed.includes(m.id));}
export function readyMilo(m,inv,progress){return !!m&&Object.entries(m.cost||{}).every(([k,n])=>(inv[k]||0)>=n)&&(!m.furniture||m.furniture.every(t=>progress.furniture.includes(t)))&&(!m.friends||progress.friends>=m.friends)&&(!m.visit||progress.visited?.[m.visit])&&(!m.treasure||progress.treasure);}
export function claimMilo(state,inv,progress,persist=()=>true){const m=currentMilo(state);if(!readyMilo(m,inv,progress))return false;const before={...inv};for(const[k,n]of Object.entries(m.cost||{}))inv[k]-=n;inv.gems=(inv.gems||0)+m.reward;state.claimed.push(m.id);if(!persist()){Object.assign(inv,before);state.claimed.pop();return false;}return true;}
export function createMiloPanel({state,inv,progress,save,message}){const root=document.getElementById('miloMissions');function render(){root.replaceChildren();const m=currentMilo(state),h=document.createElement('h3'),p=document.createElement('p');h.textContent=m?'Milo : '+m.title:'Merci, explorateur !';p.textContent=m?m.hint+' Récompense : '+m.reward+' diamants.':'Toutes mes missions sont terminées. Le camp est prêt pour de nouvelles aventures !';root.append(h,p);if(m){const b=document.createElement('button');b.textContent=m.cost?'Donner les provisions et recevoir la récompense':'Raconter à Milo et recevoir la récompense';b.disabled=!readyMilo(m,inv,progress());b.onclick=()=>{message(claimMilo(state,inv,progress(),save)?'Merci ! Ta récompense est dans ton sac 💎':'Mission incomplète ou sauvegarde indisponible.');render();};root.append(b);}const count=document.createElement('p');count.textContent=state.claimed.length+' / '+miloMissions.length+' missions accomplies · Reviens me voir après tes explorations.';root.append(count);}return {render};}
